import {SEO_LANGUAGES,seoPages,pageSeo} from './seo.js';
export function captureSeoForm(form,draft,path){return captureSeoValues(Object.fromEntries(new FormData(form)),draft,path)}
export function captureSeoValues(data,draft,path){
 const seo=draft.seo||{};seo.siteUrl=data['seo-siteUrl'];seo.titleSuffix=data['seo-titleSuffix'];seo.image=data['seo-image'];seo.googleVerification=data['seo-googleVerification'];seo.bingVerification=data['seo-bingVerification'];seo.description=Object.fromEntries(SEO_LANGUAGES.map(l=>[l,data['seo-default-'+l]||'']));seo.pages??={};seo.pages[path]={title:Object.fromEntries(SEO_LANGUAGES.map(l=>[l,data['seo-title-'+l]||''])),description:Object.fromEntries(SEO_LANGUAGES.map(l=>[l,data['seo-description-'+l]||''])),image:data['seo-page-image']||'',noindex:data['seo-noindex']==='on'};draft.seo=seo;
}
export function seoEditorMarkup(draft,path,{esc,input,area,select}){
 const seo=draft.seo||{},p=seo.pages?.[path]||{},photos=[['','Automatski odabir'],...draft.photos.map(p=>[p.key,p.alt||p.key])];
 return `<form id="seo-form" class="admin-card"><h2>SEO i dijeljenje poveznica</h2><p>Prazna polja koriste automatske podatke stranice. Promjene se spremaju u isti zaštićeni sadržaj kao apartmani i cijene te se primjenjuju bez nove programske objave.</p><details class="seo-global"><summary>Opće postavke i verifikacija tražilica</summary><div class="form-grid">${input('Glavna HTTPS adresa web stranice','seo-siteUrl',seo.siteUrl||'https://meleh.vercel.app','url','required')}${input('Dodatak naslovu (naziv objekta)','seo-titleSuffix',seo.titleSuffix||draft.name,'text','maxlength="100"')}${select('Zadana fotografija za dijeljenje','seo-image',seo.image||'',photos)}${input('Google Search Console — verifikacijski kod','seo-googleVerification',seo.googleVerification||'','text','maxlength="300"')}${input('Bing Webmaster — verifikacijski kod','seo-bingVerification',seo.bingVerification||'','text','maxlength="300"')}<p class="section-note full">Unesite samo kod iz meta oznake, bez HTML-a. Promjena glavne adrese mijenja canonical i sitemap poveznice; domenu prvo povežite s projektom na Vercelu.</p>${SEO_LANGUAGES.map(l=>area('Zadani opis · '+l.toUpperCase(),'seo-default-'+l,seo.description?.[l]||'','full')).join('')}</div></details><div class="admin-toolbar">${select('Stranica koju uređujete','seo-selected-page',path,seoPages(draft).map(p=>[p,p==='/'?'Naslovnica':p]))}</div><p class="section-note">Naslovu se automatski dodaje naziv objekta. Oko 50–60 znakova za cijeli naslov i 140–160 za opis korisne su smjernice, a prikaz ovisi o tražilici.</p>${SEO_LANGUAGES.map(l=>{const meta=pageSeo(draft,path,l);return `<fieldset class="editorial-row"><legend>${({hr:'Hrvatski',en:'Engleski',de:'Njemački',cs:'Češki'})[l]}</legend><label class="field">SEO naslov<input name="seo-title-${l}" maxlength="120" value="${esc(p.title?.[l]||'')}" placeholder="${esc(meta.title.split(' | ')[0])}" data-seo-length><small data-seo-count="seo-title-${l}"></small></label><label class="field">Meta opis<textarea name="seo-description-${l}" maxlength="320" placeholder="${esc(meta.description)}" data-seo-length>${esc(p.description?.[l]||'')}</textarea><small data-seo-count="seo-description-${l}"></small></label></fieldset>`}).join('')}<div class="form-grid">${select('Fotografija za dijeljenje ove stranice','seo-page-image',p.image||'',photos)}<label class="consent"><input type="checkbox" name="seo-noindex" ${p.noindex?'checked':''}><span>Isključi ovu stranicu iz indeksiranja (noindex)</span></label></div><section class="seo-preview"><h3>Pregled rezultata pretraživanja</h3>${select('Jezik pregleda','seo-preview-language','hr',SEO_LANGUAGES.map(l=>[l,l.toUpperCase()]))}<div class="seo-snippet"><p data-seo-preview-url></p><h4 data-seo-preview-title></h4><p data-seo-preview-description></p></div><p class="section-note" data-seo-preview-index></p><p class="section-note">Informativni pregled. Google i druge tražilice mogu odabrati drukčiji naslov, opis ili fotografiju.</p></section><div class="actions"><button class="btn">Spremi SEO postavke ↗</button><a class="text-link" href="/sitemap.xml" target="_blank" rel="noopener">Sitemap ↗</a><a class="text-link" href="/robots.txt" target="_blank" rel="noopener">Robots.txt ↗</a></div><p class="section-note">Administracija, privatni vodič za goste i nepostojeće stranice uvijek imaju noindex. Te se postavke ovdje ne mogu isključiti.</p></form>`;
}
export function bindSeoPreview(form,draft,path){
 const refresh=()=>{try{const preview=structuredClone(draft);captureSeoForm(form,preview,path);const language=form.elements['seo-preview-language'].value;const meta=pageSeo(preview,path,language);form.querySelector('[data-seo-preview-url]').textContent=meta.canonical;form.querySelector('[data-seo-preview-title]').textContent=meta.title;form.querySelector('[data-seo-preview-description]').textContent=meta.description;form.querySelector('[data-seo-preview-index]').textContent=meta.noindex?'Ova stranica neće biti uključena u sitemap i tražilicama šalje noindex.':'Ova stranica dopušta indeksiranje i uključena je u sitemap.';form.querySelectorAll('[data-seo-length]').forEach(field=>{form.querySelector('[data-seo-count="'+field.name+'"]').textContent=field.value.length+' znakova'})}catch{form.querySelector('[data-seo-preview-index]').textContent='Provjerite glavnu HTTPS adresu stranice.'}};
 form.addEventListener('input',refresh);form.addEventListener('change',refresh);refresh();
}
